  "profile.public.linkHint": "\u0421\u0441\u044b\u043b\u043a\u0430 \u043d\u0438\u0436\u0435 \u044d\u0442\u043e \u043a\u043d\u043e\u043f\u043a\u0430 \u043d\u0430 \u0432\u0430\u0448\u0435\u0439 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 (\u0432\u0430\u0448 \u0441\u0430\u0439\u0442 \u0438\u043b\u0438 \u0441\u043e\u0446\u0441\u0435\u0442\u044c). \u0427\u0442\u043e\u0431\u044b \u0441\u043c\u0435\u043d\u0438\u0442\u044c \u043a\u0430\u0440\u0442\u0438\u043d\u043a\u0443 \u043f\u0440\u043e\u0444\u0438\u043b\u044f, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 \u043f\u043e\u043b\u0435 \u0430\u0432\u0430\u0442\u0430\u0440\u0430 \u0432\u044b\u0448\u0435.",
