  "core.story.topup": "Вложить в ядро",
  "core.story.1.title": "То, что остаётся",
  "core.story.1.body": "Деньги приходят и уходят. Работа меняется, планы сдвигаются, обстоятельства бывают сильнее нас. Но у каждого пути должно быть что-то, что остаётся с тобой. Для этого и придумано ядро.",
  "core.story.2.title": "Твоё и только твоё",
  "core.story.2.body": "Ядро личное: его нельзя передать, продать или отнять. И оно не уменьшается. Ни пропущенный день, ни трудная неделя, ни ошибка не отнимут то, что уже накоплено.",
  "core.story.3.title": "Оно работает каждый день",
  "core.story.3.body": "Пока ты живёшь своей жизнью, ядро приносит расчётный доход: сейчас 0,0633% в день. Часть можно вернуть в ядро, и оно вырастет быстрее, а часть уходит в кошелёк. Это расчёт по правилам системы, а не обещание дохода.",
  "core.story.4.title": "Ты задаёшь темп",
  "core.story.4.body": "Ядро растёт от полезных шагов, которые ты доводишь до результата, и от денег, которые ты решаешь вложить из кошелька. Назад в кошелёк ядро не возвращается, поэтому вкладывай то, что готов оставить расти надолго.",
