  "challenges.reason.not_connected": "Проверка этого квеста пока не подключена. Это наша задача, не ваша.",
  "challenges.reason.check_failed": "Не удалось проверить, это наша ошибка. Попробуйте ещё раз через минуту.",
  "challenges.reason.wrong_code": "\u041a\u043e\u0434 \u043d\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442. \u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0438\u043b\u0438 \u043f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u043a\u043e\u0434 \u0435\u0449\u0451 \u0440\u0430\u0437.",
  "challenges.code.send": "\u041f\u0440\u0438\u0441\u043b\u0430\u0442\u044c \u043a\u043e\u0434",
  "challenges.code.resend": "\u041f\u0440\u0438\u0441\u043b\u0430\u0442\u044c \u0435\u0449\u0451 \u0440\u0430\u0437",
  "challenges.code.sent.telegram": "\u041a\u043e\u0434 \u0443 \u0432\u0430\u0441 \u0432 Telegram, \u0432 \u0447\u0430\u0442\u0435 \u0441 \u0431\u043e\u0442\u043e\u043c Open Abundance.",
  "challenges.code.sent.push": "\u041f\u0443\u0448 \u0441 \u043a\u043e\u0434\u043e\u043c \u043f\u0440\u0438\u0434\u0451\u0442 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u043c\u0438\u043d\u0443\u0442\u044b.",
  "challenges.code.sent.nova": "\u041d\u043e\u0432\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043b\u0430 \u0432\u0430\u043c \u043a\u043e\u0434. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0447\u0430\u0442 \u0441 \u041d\u043e\u0432\u043e\u0439 \u0438 \u0432\u0435\u0440\u043d\u0438\u0442\u0435\u0441\u044c \u0441\u044e\u0434\u0430.",
  "challenges.code.openNova": "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u041d\u043e\u0432\u0443",
  "challenges.code.problem.telegram_not_linked": "Telegram \u0435\u0449\u0451 \u043d\u0435 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d \u043a \u044d\u0442\u043e\u043c\u0443 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0443. \u041f\u0440\u0438\u0432\u044f\u0436\u0438\u0442\u0435 \u0435\u0433\u043e \u0438 \u043f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u043a\u043e\u0434 \u0441\u043d\u043e\u0432\u0430.",
  "challenges.code.problem.bot_not_started": "\u0411\u043e\u0442 \u043f\u043e\u043a\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0432\u0430\u043c \u043f\u0438\u0441\u0430\u0442\u044c. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0431\u043e\u0442\u0430, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 Start \u0438 \u043f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u043a\u043e\u0434 \u0441\u043d\u043e\u0432\u0430.",
  "challenges.code.problem.no_push_device": "\u041f\u0443\u0448\u0438 \u043d\u0430 \u044d\u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u044b. \u0412\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0438\u0445, \u0438 \u043a\u043e\u0434 \u043f\u0440\u0438\u0434\u0451\u0442 \u0441\u0440\u0430\u0437\u0443.",
  "challenges.code.enablePush": "Включить уведомления",
  "challenges.code.problem.failed": "\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043a\u043e\u0434. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 \u043c\u0438\u043d\u0443\u0442\u0443.",
  "challenges.code.label": "\u041a\u043e\u0434",
  "challenges.code.required": "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u043a\u043e\u0434 \u0438\u0437 6 \u0446\u0438\u0444\u0440.",
  "telegramBot.prompt.title": "\u0423\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u0438 \u0432 Telegram",
  "telegramBot.prompt.bodyAllow": "Разреши боту Open Abundance писать тебе: так ты не пропустишь новые награды и доход в Core.",
  "telegramBot.prompt.allow": "Разрешить",
  "telegramBot.prompt.bodyStart": "\u041a\u0430\u0436\u0434\u044b\u0439 \u043f\u0443\u0448 \u0434\u0443\u0431\u043b\u0438\u0440\u0443\u0435\u0442 \u0431\u043e\u0442 Open Abundance. \u041d\u0430\u0436\u043c\u0438\u0442\u0435 Start \u0432 \u0431\u043e\u0442\u0435, \u0447\u0442\u043e\u0431\u044b \u043e\u043d \u043c\u043e\u0433 \u0432\u0430\u043c \u043f\u0438\u0441\u0430\u0442\u044c.",
  "telegramBot.prompt.bodyLink": "\u041f\u0440\u0438\u0432\u044f\u0436\u0438\u0442\u0435 Telegram, \u0438 \u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u0443\u0448 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0435\u0449\u0451 \u0438 \u043e\u0442 \u0431\u043e\u0442\u0430 Open Abundance.",
  "challenges.explainer.title": "Квесты: ваш путь роста",
