  "challenges.explainer.step1.body": "Выберите шаг, который вам сейчас интересен.",
  "challenges.explainer.step2.title": "Сделайте",
  "challenges.explainer.step2.body": "В каждой карточке написано, зачем это нужно и что именно сделать.",
  "challenges.explainer.step3.title": "Проверьте и получите Core",
  "challenges.explainer.step3.body": "Проверка обычно автоматическая. Core остаётся с вами навсегда и растёт каждый день.",
  "challenges.explainer.benefit1.title": "Шаги к вашему желанию",
  "challenges.explainer.benefit1.body": "Каждый квест двигает вас к цели, а не просто даёт очки.",
