  "challenges.explainer.benefit3.title": "Core навсегда",
  "challenges.explainer.benefit3.body": "Полученный Core не уменьшается и приносит 0,0633 % в день.",
  "challenges.explainer.benefit4.title": "Новые уровни",
  "challenges.explainer.benefit4.body": "Больше Core — больше доступных квестов.",
  "challenges.explainer.withdraw.question": "Как вывести деньги?",
  "challenges.explainer.withdraw.answer": "Деньги можно вывести с кошелька (Wallet) — в разделе «Кошелёк». Доход от Core ежедневный и пожизненный: Core остаётся с вами навсегда, его нельзя вывести, но часть дохода, которую вы не реинвестируете, каждый день приходит на кошелёк. Чтобы получать задания с наградой на кошелёк, повышайте уровень. Сейчас вам доступны реферальные бонусы и «Я не робот» с выплатой на кошелёк. Ещё на кошелёк приходит лидерский бонус с роста Core вашей команды.",
