  "invite.title": "Пригласить друга",
  "invite.intro": "Выберите сообщение, отправьте его и отметьте в списке, куда уже отправили. Ваша личная ссылка уже вставлена в текст.",
  "invite.yourLink": "Ваша ссылка",
  "invite.linkFailed": "Ссылка станет доступна после первого результата. Выполните любой начальный челлендж и вернитесь.",
  "invite.textsTitle": "Готовые сообщения",
  "invite.copy": "Скопировать",
  "invite.copied": "Скопировано",
