  "invite.checklistTitle": "Куда отправить",
  "invite.checklistProgress": "Отмечено: {done} из {total}",
  "invite.rules": "Пишите по одному человеку, без массовых рассылок. Не называйте суммы и не обещайте доход: награды за задания — внутренние баллы Core.",
  "invite.text.1": "Заглянул(а) в Open Abundance и залип(ла): там люди делятся, как исполняют свои желания, от путешествий до своих небольших дел. Посмотри сам(а), пока интересно: {link}",
  "invite.text.2": "Пока все обсуждают ИИ, в этом приложении он уже помогает людям с реальными желаниями: что делать сегодня, с чего начать, как не бросить. Глянь, как это выглядит: {link}",
  "invite.text.3": "Любопытно посмотреть, чем занимаются другие: кто-то учится новому, кто-то начинает небольшие услуги и подработки, кто-то копит на мечту. Зайди и сравни со своими планами: {link}",
  "invite.text.4": "Там за пару минут выбираешь своё желание и видишь первый шаг, а ещё считается ежедневное начисление от твоих баллов, в приложении видно, сколько. Бесплатно: {link}",
  "invite.text.5": "Смотри, что нашёл(ла): {link}. Люди исполняют желания вместе с ИИ. Проще один раз посмотреть, чем объяснять.",
  "invite.channel.1": "Близкий друг (личное сообщение)",
  "invite.channel.2": "Семейный чат",
