  "humanity.title": "Я не робот",
  "humanity.intro": "Короткая проверка внешним провайдером: лицо в камеру, провайдер может запросить документ. Она открывает награды, которым нужен уникальный человек, например лидерский бонус в Wallet. Пользоваться приложением можно и без неё.",
  "humanity.consent": "Согласен(на) на проверку: внешний провайдер обработает видео лица и, возможно, документ и сообщит нам только результат. Мы не храним видео, фото, биометрию и документы.",
  "humanity.start": "Пройти проверку",
  "humanity.waiting": "Проверка обрабатывается, это обычно занимает несколько минут.",
