  "humanity.startFailed": "Не удалось начать проверку. Повторите позже.",
  "humanity.telegramBrowser": "Проверка откроется в браузере телефона: там работает камера. После проверки вернись в Telegram, результат появится здесь.",
  "humanity.alternative": "Не хотите проходить онлайн или не получается? Напишите нам через «Предложить улучшение», подтвердим вручную.",
  "social.teams.bonus.note": "Лидерский бонус зачисляется в Wallet только если подтверждены как люди и вы, и участник вашей команды. Иначе он зачисляется в Core.",
