  "dailySet.combo.missing": "\u0414\u043b\u044f \u043a\u043e\u043c\u0431\u043e \u0434\u043d\u044f: \u0437\u0430\u0433\u0430\u0434\u043a\u0430 \u0438 \u0435\u0449\u0451 \u0434\u0432\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f.",
  "riddle.1": "\u041c\u043e\u0439 \u043b\u0438\u0447\u043d\u044b\u0439 \u0444\u043e\u043d\u0434 \u0440\u0430\u0441\u0442\u0451\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u043d\u044c \u0438 \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u043f\u043e \u043d\u0430\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0443. \u041a\u0430\u043a \u043e\u043d \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438?",
  "riddle.1.hint": "4 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u0438\u0435 \u0431\u0443\u043a\u0432\u044b, \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u043d\u0430 C.",
  "riddle.2": "\u041a\u0430\u043a \u0437\u043e\u0432\u0443\u0442 \u0418\u0418-\u043f\u043e\u043c\u043e\u0449\u043d\u0438\u0446\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u0440\u0430\u0437\u0431\u0438\u0442\u044c \u0436\u0435\u043b\u0430\u043d\u0438\u0435 \u043d\u0430 \u0448\u0430\u0433\u0438?",
  "riddle.2.hint": "\u043e\u043d\u0430 \u0437\u0434\u043e\u0440\u043e\u0432\u0430\u0435\u0442\u0441\u044f \u0441 \u0442\u043e\u0431\u043e\u0439 \u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u043e\u0439.",
  "riddle.3": "\u0413\u0434\u0435 \u043b\u0435\u0436\u0430\u0442 \u0434\u0435\u043d\u044c\u0433\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043c\u043e\u0436\u043d\u043e \u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0432\u043d\u0443\u0442\u0440\u0438 \u0438 \u0432\u044b\u0432\u043e\u0434\u0438\u0442\u044c?",
  "riddle.3.hint": "\u044d\u0442\u043e \u043e\u0434\u0438\u043d \u0438\u0437 \u0440\u0430\u0437\u0434\u0435\u043b\u043e\u0432 \u0432 \u043d\u0438\u0436\u043d\u0435\u043c \u043c\u0435\u043d\u044e.",
  "riddle.4": "\u041a\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0440\u0430\u0437\u0434\u0435\u043b, \u0433\u0434\u0435 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u0434\u0430\u044e\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443 \u0443\u0441\u043b\u0443\u0433\u0438 \u0438 \u0432\u0435\u0449\u0438?",
  "riddle.4.hint": "\u043e\u0434\u043d\u043e \u043a\u043e\u0440\u043e\u0442\u043a\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0432 \u043c\u0435\u043d\u044e.",
  "riddle.5": "\u041f\u0443\u0442\u044c \u043a \u0436\u0435\u043b\u0430\u043d\u0438\u044e: \u0416\u0435\u043b\u0430\u043d\u0438\u0435, \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442, \u041f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u0435 \u0438\u2026 \u0447\u0442\u043e \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043e\u0435?",
  "riddle.5.hint": "\u043e\u0442\u043a\u0440\u043e\u0439 \u0441\u0432\u043e\u0451 \u0436\u0435\u043b\u0430\u043d\u0438\u0435, \u0442\u0430\u043c \u0435\u0441\u0442\u044c \u043a\u043d\u043e\u043f\u043a\u0430 \u043f\u0440\u043e \u043f\u0443\u0442\u044c \u043a \u043d\u0435\u043c\u0443.",
  "riddle.6": "\u041a\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043d\u0435\u0432\u043d\u0438\u043a, \u0433\u0434\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0441\u0430\u043c\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0438 \u043e\u0431\u043e\u0440\u043e\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430?",
  "riddle.6.hint": "\u0435\u0433\u043e \u0432\u0438\u0434\u043d\u043e \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435: \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u043f\u043e \u0434\u043d\u044f\u043c \u0438 \u0433\u0440\u0430\u0444\u0438\u043a.",
  "riddle.7": "\u041a\u043e\u0433\u043e \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u043f\u043e\u0441\u043b\u0435 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0437\u0430\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435?",
  "riddle.7.hint": "\u043e\u0442\u0432\u0435\u0442 \u0432 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438: \u00ab\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435, \u0447\u0442\u043e \u0432\u044b\u2026\u00bb.",
  "riddle.8": "\u0421 \u0447\u0435\u0433\u043e \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u043f\u0443\u0442\u044c \u0432 Open Abundance? \u041e\u0434\u043d\u043e \u0441\u043b\u043e\u0432\u043e.",
  "riddle.8.hint": "\u0435\u0441\u0442\u044c \u0446\u0435\u043b\u044b\u0439 \u0440\u0430\u0437\u0434\u0435\u043b \u0441 \u0442\u0430\u043a\u0438\u043c \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435\u043c.",
  "riddle.9": "\u041a\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u0438\u0442\u0440\u0438\u043d\u0430, \u0433\u0434\u0435 \u0441\u043e\u0431\u0440\u0430\u043d\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0435 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432?",
  "riddle.9.hint": "\u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 /stories.",
  "riddle.10": "\u041a\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0437\u0430\u0434\u0430\u043d\u0438\u0435, \u0437\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0434\u0430\u0451\u0442 \u043d\u0430\u0433\u0440\u0430\u0434\u0443, \u043a\u043e\u0433\u0434\u0430 \u0442\u044b \u0440\u0430\u0441\u0442\u0438\u0448\u044c \u043e\u0431\u0449\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443?",
  "riddle.10.hint": "\u044d\u0442\u043e \u0440\u0430\u0437\u0434\u0435\u043b \u0432 \u043c\u0435\u043d\u044e.",
