  "practice.childState.title": "Состояние ребёнка",
  "practice.childState.desc": "Открытость, гибкость, любопытство, увлечённость процессом без страха ошибок. Вспомни детское увлечение и сделай это сегодня как игру, без цели на результат. Мир — приключение, каждый день — открытие",
  "practice.liberation.title": "Освобождение",
